module top_module(clk, reset, count);input clk;
input reset;
output reg [3:0] count;

always @ (posedge clk or posedge reset)
begin
  if (reset == 1'b1) // Asynchronous reset
    count <= 4'b0000;
  else if (count == 4'b1111) // Wrap around
    count <= 4'b0000;
  else
    count <= count + 1; // Increment count
end

