    wire [31:0] F;

    // Assuming RAM_B is to be replaced with a behavioral model.
    always @(posedge Clk) begin
        if (Mem_Write) begin
            case (Mem_Addr[1:0]) // Only need lower 2 bits for a 4-entry memory
                2'b00: mem[0] <= dina;
                2'b01: mem[1] <= dina;
                2'b10: mem[2] <= dina;
                2'b11: mem[3] <= dina;
            endcase
        end
