description:
Design a power-on reset (POR) circuit that generates a reset signal for a specified duration following the application of power. When the power signal transitions from LOW to HIGH, the reset output is asserted HIGH and maintained for a defined duration (controlled by the `rst_time` parameter). After the specified duration, the reset signal is de-asserted to LOW, allowing normal operation of the system. The reset process is synchronized with the clock signal, ensuring reliable timing during the power-up sequence.
module top_module(
  input clk,
  input pwr,
  output reg rst
);

code:
module top_module(
  input clk,
  input pwr,
  output reg rst
);parameter rst_time = 10; // duration for which the reset signal should be asserted

reg pwr_prev; // previous value of power signal
reg [3:0] rst_count; // counter for reset signal duration

always @(posedge clk) begin
  if (pwr && !pwr_prev) begin // power has just been applied
    rst <= 1;
    rst_count <= 0;
  end else if (rst_count < rst_time) begin // reset signal is still being asserted
    rst <= 1;
    rst_count <= rst_count + 1;
  end else begin // reset signal has been de-asserted
    rst <= 0;
  end

  pwr_prev <= pwr;
end

endmodule

