description:
Implement the Verilog module based on the following description.
Module X implements the boolean function z = (x ^ ~y).

// Module Y can be described by the following simulation waveform: 

If x = 1, y = 1, then z = 0.
If x = 0, y = 1, then z = 1.
If x = 0, y = 0, then z = 0.
If x = 1, y = 0, then z = 1.

// Now consider a top-level that uses two X submodules and two Y submodules. The first input of all four submodules is connect to input 'p', and the second input of all four submodules is connected to 'q'. The output of the first X submodule is connected to a two-input OR gate, along with the output of the first Y submodule. The second pair of X and Y submodules is similarly connected to an AND gate. The output of the OR and the AND is connected to an XOR, whose output is 'z'.

// Implement this circuit in Verilog.

module top_module(
    input p,
    input q,
    output z);

code:
module X(
    input p,
    input q,
    output z
);
    assign z = (p ^ ~q);
endmodule

module Y(
    input p,
    input q,
    output z
);
    assign z = (p ^ ~q);
endmodule

module top_module(
    input p,
    input q,
    output z
);
    wire x1_out, x2_out, y1_out, y2_out;
    wire or_out, and_out;

    X x1(.p(p), .q(q), .z(x1_out));
    X x2(.p(p), .q(q), .z(x2_out));
    Y y1(.p(p), .q(q), .z(y1_out));
    Y y2(.p(p), .q(q), .z(y2_out));

    assign or_out = x1_out | y1_out;
    assign and_out = x2_out & y2_out;

    assign z = or_out ^ and_out;
endmodule

