description:
Design a hazard detection unit for a pipelined CPU architecture. This module determines if a stall condition is necessary based on memory read signals and destination register dependencies. It checks if the current instruction is trying to read from a register that is being updated by a previous instruction that is still in the memory stage. If a stall condition is detected either from the execution stage or the memory stage, the output signal 'Stall' is asserted to prevent data hazards and ensure correct instruction execution.
module top_module(
    ID_EX_MemRead, EX_MEM_MemRead, EX_Rd, ID_Rs, ID_Rt, EX_MEM_Rd, PCSrc, Stall
    );

code:
module top_module(
    ID_EX_MemRead, EX_MEM_MemRead, EX_Rd, ID_Rs, ID_Rt, EX_MEM_Rd, PCSrc, Stall
    );input ID_EX_MemRead;
    input EX_MEM_MemRead;
    input [4:0] EX_Rd;
    input [4:0] ID_Rs;
    input [4:0] ID_Rt;
    input [4:0] EX_MEM_Rd;
    input [2:0] PCSrc;
    output Stall;

    wire EX_Stall, MEM_Stall;

    assign EX_Stall = (ID_EX_MemRead) && (EX_Rd != 5'b00000)&& ((EX_Rd == ID_Rs) || (EX_Rd == ID_Rt));
    assign MEM_Stall = (EX_MEM_MemRead) && (EX_MEM_Rd != 5'b00000) && (EX_MEM_Rd == ID_Rs);
    assign Stall = EX_Stall || (PCSrc == 3'b010 && MEM_Stall); 

endmodule

