module timer (
	input clk,
	input resetn,
	input start,
	output done);

	parameter IDLE=0, COUNTING=1, DONE=2;
	reg [1:0] state, next_state;
	reg [3:0] counter;

	always @(posedge clk) begin
		if (~resetn) state <= IDLE;
		else state <= next_state;
	end

	always @(posedge clk) begin
		if (state == COUNTING) counter <= counter + 1;
		else counter <= 0;
	end

	always_comb begin
		case (state)
			IDLE: next_state = start ? COUNTING : IDLE;
			COUNTING: next_state = (counter == 4'b1111) ? DONE : COUNTING;
			DONE: next_state = IDLE;
			default: next_state = IDLE;
		endcase
	end

	assign done = (state == DONE);
endmodule

