    if (sof) begin
        A_reg <= A;
        B_reg <= B;
        valid <= 0;
        C_reg <= 0;
    end else begin
        A_reg <= A_reg;
        B_reg <= B_reg;
        valid <= 0;
        C_reg <= C_reg;
    end
