    A_shifted = {A_reg, 24'h0};
    B_shifted = {16'h0, B_reg};
    AB_mult = A_shifted * B_shifted;
    C_reg = {AB_mult[175:96], AB_mult[95:16], AB_mult[15:0]};
    valid = 1;
end

assign C = C_reg;

endmodule

