module top_module (
	input clk,
	input areset,
	input x,
	input y,
	output z);parameter EQUAL=0, NOT_EQUAL=1;
	reg state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= EQUAL;
		else begin
			case (state)
				EQUAL: state <= (x == y) ? EQUAL : NOT_EQUAL;
				NOT_EQUAL: state <= NOT_EQUAL;
			endcase
		end
	end

	assign z = (state == EQUAL);

endmodule

