module top_module(
    input clk,
    input reset,
    input [7:0] d,
    input [7:0] in,
    output [6:0] seg
);reg [7:0] reg_value;
reg [7:0] prev_in;
reg [7:0] edge_detected;
wire [7:0] sum;

always @(negedge clk) begin
    if (reset) begin
        reg_value <= 8'h34;
    end else begin
        reg_value <= sum;
    end
end

always @(posedge clk) begin
    edge_detected <= (in ^ prev_in);
    prev_in <= in;
end

assign sum = reg_value + edge_detected;

reg [6:0] seg_temp;
always @(*) begin
    case (sum)
        4'h0: seg_temp = 7'b1000000;
        4'h1: seg_temp = 7'b1111001;
        4'h2: seg_temp = 7'b0100100;
        4'h3: seg_temp = 7'b0110000;
        4'h4: seg_temp = 7'b0011001;
        4'h5: seg_temp = 7'b0010010;
        4'h6: seg_temp = 7'b0000010;
        4'h7: seg_temp = 7'b1111000;
        4'h8: seg_temp = 7'b0000000;
        4'h9: seg_temp = 7'b0010000;
        default: seg_temp = 7'b1111111;
    endcase
end

assign seg = seg_temp;

endmodule

