    reg [11:0] GREEN = 12'h083;
    reg [11:0] YELLOW = 12'hff3;
    reg [11:0] RED = 12'he12;
    reg [11:0] WHITE = 12'hfff;

    always @(code)
    begin
        case(code)
            3'b000 : hex = BLACK;
            3'b001 : hex = GREY;


            3'b011 : hex = ORANGE;
            3'b100 : hex = GREEN;
            3'b101 : hex = YELLOW;
            3'b110 : hex = RED;
            3'b111 : hex = WHITE;

        endcase
    end

endmodule

