    if(RST == 0) begin
      reg3 <= 0;
    end else begin
      reg3 <= in1;
    end
  end

  always @(posedge CLK or negedge RST) begin
    if(RST == 0) begin
      reg4 <= 1;
    end else begin
      if(in1 == 1) begin
        reg4 <= ~reg4;
      end
    end
  end

endmodule

