module top_module_tb;

    // Testbench signals (sequential circuit)
    reg [7:0] b1_strobe;
    reg [7:0] b2_strobe;
    reg clk;
    reg [1:0] no_bunches;
    reg [3:0] no_samples;
    reg [7:0] sample_spacing;
    reg store_strb;
    wire LUTcond;
    wire bunch_strb;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    top_module dut (
        .b1_strobe(b1_strobe),
        .b2_strobe(b2_strobe),
        .clk(clk),
        .no_bunches(no_bunches),
        .no_samples(no_samples),
        .sample_spacing(sample_spacing),
        .store_strb(store_strb),
        .LUTcond(LUTcond),
        .bunch_strb(bunch_strb)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            b1_strobe = 8'h00;
            b2_strobe = 8'h00;
            no_bunches = 2'b00;
            no_samples = 4'h0;
            sample_spacing = 8'h00;
