            repeat(2) @(posedge clk);
        end
        endtask
    task testcase001;

        begin
            test_num = test_num + 1;
            $display("\nTestcase %03d: 1 Bunch, 4 Samples", test_num);
            reset_dut();


            no_bunches = 2'd1;
            no_samples = 4'd4;
            sample_spacing = 8'd1;
            b1_strobe = 8'd1;
            b2_strobe = 8'd4;

            @(posedge clk);


            repeat (4) begin
                store_strb = 1;
                @(posedge clk);
                store_strb = 0;
                repeat (2) @(posedge clk);
